from taf.ul.ettf.logger.logger import custom_logger
from taf.ul.ettf.scheduler.robot_policy_trigger import RobotPolicyTrigger


logger = custom_logger('LogAnalysisPolicy')


class LogAnalysisPolicyTrigger(RobotPolicyTrigger):
    def _policy_name(self):
        return 'LOG_ANALYSIS_POLICY'

    @staticmethod
    def _run_callback(_callback, context):
        return _callback()


log_analysis_policy_trigger = LogAnalysisPolicyTrigger
